const cats=['업무 경험','독서','뉴스','관심사'],folders=['01-HR','02-독서','03-뉴스','04-관심사'];
const samples=[['업무 경험','온보딩 경험을 설계하는 방법','HR,온보딩','입사 첫날부터 90일까지, 구성원의 여정을 따라 개선 지점을 정리하는 프로젝트 템플릿입니다.\n\n문제 정의\n어떤 어려움을 발견했나요?\n\n나의 역할과 실행\n직접 수행한 일을 적어보세요.\n\n결과와 배운 점\n확인 가능한 성과와 다음 과제를 남겨보세요.'],['독서','읽고, 생각하고, 일에 연결하기','독서노트,성장','책에서 인상 깊었던 생각을 자신의 언어로 정리해 보세요.\n\n책 제목 / 저자\n핵심 내용\n나의 생각\nHR 업무에 적용할 한 가지'],['뉴스','변화하는 일의 모습을 관찰하기','트렌드,일의미래','관심 있는 기사의 원문 링크와 발행일을 함께 기록해 보세요.\n\n핵심 요약\n왜 주목했나요?\n나의 관점\n추가로 확인할 내용'],['관심사','일상에서 발견한 작은 영감','영감,라이프','전시, 공간, 대화에서 발견한 생각을 모으는 공간입니다.\n\n무엇을 발견했나요?\n어떤 점이 좋았나요?\n나의 일과 어떤 연결이 있나요?']].map((a,i)=>({category:a[0],title:a[1],tags:a[2].split(','),body:a[3],date:'2026-10-30',id:'sample'+i}));
let notes=[...publishedNotes,...samples],category='업무 경험',tag='',root=null,example=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){for(const sel of ['#nav','#tabs'])$(sel).innerHTML=cats.map((c,i)=>`<button data-cat="${c}" class="${category===c?'active':''}">${sel==='#nav'?['▤　','▥　','▧　','✳　'][i]:''}${c}${sel==='#nav'?`<span>${notes.filter(n=>n.category===c).length}</span>`:''}</button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;tag='';render()});
const base=notes.filter(n=>n.category===category),tags=[...new Set(base.flatMap(n=>n.tags))];$('#tags').innerHTML=['',...tags].map(t=>`<button class="${tag===t?'active':''}" data-tag="${esc(t)}">${t?'# '+esc(t):'모든 태그'}</button>`).join('');document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{tag=b.dataset.tag;render()});
const q=$('#search').value.toLowerCase(),list=base.filter(n=>(!tag||n.tags.includes(tag))&&[n.title,n.body,...n.tags].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date));$('#heading').firstChild.textContent=category+' ';$('#count').textContent=list.length;
$('#grid').innerHTML=list.map(n=>{const i=Math.max(0,cats.indexOf(n.category));return `<button class="card" data-id="${esc(n.id)}"><div class="cover c${i}"><strong>${['People &\npossibilities.','Between\nthe pages.','A changing\nworld.','Stay\ncurious.'][i]}</strong><span>${['◫','▥','↗','✳'][i]}</span></div><div class="cardbody"><div class="meta"><span>${esc(n.category)}${n.id.startsWith('sample')?' · EXAMPLE':''}</span><span>${esc(n.date)}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.summary||n.body)}</p><div class="cardtags">${n.tags.map(t=>'#'+esc(t)).join('　')}</div></div></button>`}).join('')||'<div class="empty">아직 기록이 없습니다.<br>새 기록을 남겨 나의 아카이브를 시작해 보세요.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openNote(notes.find(n=>n.id===b.dataset.id)));}
function openNote(n){let url='';try{const u=new URL(n.url);if(['http:','https:'].includes(u.protocol))url=u.href}catch{}$('#detailbody').innerHTML=`<div class="eyebrow">${esc(n.category)}</div><h2>${esc(n.title)}</h2><p class="detail-meta">${esc(n.date)}${n.author?' · '+esc(n.author)+' 저':''}${n.rating?' · '+esc(n.rating):''} · ${n.tags.map(esc).join(' / ')}</p>${url?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">원문 보기 ↗</a></p>`:''}<div class="note-body${n.html?' article-body':''}">${n.html||esc(n.body)}</div>`;$('#detail').showModal()}
function parse(text,path){const m=text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n/),meta={};if(m)for(const l of m[1].split(/\r?\n/)){const p=l.indexOf(':');if(p>0)meta[l.slice(0,p).trim()]=l.slice(p+1).trim()}let body=m?text.slice(m[0].length):text;const inferred=folders.findIndex(f=>f&&path.includes(f));return{id:path,title:meta.title||body.match(/^#\s+(.+)$/m)?.[1]||path.split('/').pop().replace(/\.(md|txt)$/i,''),category:meta.category==='HR 포트폴리오'?'업무 경험':cats.includes(meta.category)?meta.category:cats[inferred>=0?inferred:3],date:/^\d{4}-\d{2}-\d{2}$/.test(meta.date)?meta.date:'',tags:(meta.tags||'').split(',').map(t=>t.trim()).filter(Boolean),url:meta.url||'',body:body.replace(/^#\s+.+\r?\n/,'').trim()}}
async function readFolder(){const found=[];async function walk(dir,prefix=''){for await(const [name,h]of dir.entries()){if(name.startsWith('.'))continue;if(h.kind==='directory')await walk(h,prefix+name+'/');else if(/\.(md|txt)$/i.test(name)){const f=await h.getFile();if(f.size<2000000)found.push(parse(await f.text(),prefix+name))}}}await walk(root);notes=found;example=false;render()}
$('#search').oninput=render;document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#new').onclick=()=>{$('#form').reset();$('#form [name=date]').value=new Date().toLocaleDateString('sv-SE');$('#saveinfo').textContent=root?'연결한 폴더에 Markdown 파일로 저장합니다.':'Markdown 파일을 다운로드합니다. 나의 아카이브의 해당 분류 폴더에 저장하세요.';$('#editor').showModal()};
$('#form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),filename=v.date+'-'+v.title.replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').slice(0,90)+'.md',text=`---\ntitle: ${v.title}\ncategory: ${v.category}\ndate: ${v.date}\ntags: ${v.tags}\nurl: ${v.url}\n---\n\n${v.body}\n`;try{if(root){const d=await root.getDirectoryHandle(folders[cats.indexOf(v.category)],{create:true});try{await d.getFileHandle(filename);alert('같은 날짜와 제목의 파일이 있습니다. 제목을 변경해 주세요.');return}catch(err){if(err.name!=='NotFoundError')throw err}const f=await d.getFileHandle(filename,{create:true}),w=await f.createWritable();await w.write(text);await w.close();await readFolder()}else{const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);if(example)notes=[];example=false;notes.push(parse(text,filename));render()}$('#editor').close()}catch(err){alert('저장하지 못했습니다: '+err.message)}};

function showHelp(extra=''){$('#detailbody').innerHTML=`<div class="eyebrow">LOCAL FIRST</div><h2>내 컴퓨터에서 관리하는 기록</h2>${extra?'<p>'+esc(extra)+'</p>':''}<div class="note-body">1. 제공된 ‘나의 아카이브’ 폴더를 사용하세요.\n2. ‘로컬 폴더 연결’에서 해당 폴더를 선택하고 권한을 허용하세요. Chrome·Edge 데스크톱을 권장합니다.\n3. ‘새 기록’으로 작성하면 분류별 폴더에 .md 파일로 저장됩니다.\n4. 외부 편집기로 수정한 뒤 ‘폴더 새로고침’을 누르세요.\n\n01-HR / 02-독서 / 03-뉴스 / 04-관심사\n\n폴더 연결은 브라우저의 권한을 사용하며 다시 방문하면 재연결이 필요합니다. 로컬 기록은 서버에 업로드되지 않습니다. 파일 가져오기는 현재 탭에서만 유지되므로 원본 파일을 보관하세요. 파일 다운로드 방식에서는 다운로드한 파일을 직접 분류 폴더에 옮겨주세요.</div>`;$('#detail').showModal()}render();

const linkedNote=notes.find(n=>n.id===location.hash.slice(1));if(linkedNote){category=linkedNote.category;render();openNote(linkedNote);}
